"use client";

/**
 * Endpoint list plus the "add endpoint" form.
 *
 * Owner D. Private to the webhooks route. The event-type checkboxes are driven
 * by `webhookEventTypeSchema` so the list of subscribable events cannot drift
 * from what the server will accept.
 */

import { useActionState } from "react";
import { fieldErrorsFromZod } from "@/lib/errors";
import { createWebhookSchema, webhookEventTypeSchema } from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { ActionResult } from "@/types/api";
import type { OrgId, WebhookId } from "@/types/common";

export type WebhookManagerProps = {
  orgId: OrgId;
  endpoints: readonly WebhookEndpointRow[];
  atLimit: boolean;
  onCreate: (input: unknown) => Promise<ActionResult<WebhookEndpointRow>>;
  onDelete: (input: unknown) => Promise<ActionResult<null>>;
};

type CreateState = ActionResult<WebhookEndpointRow> | null;

const EVENT_TYPES = webhookEventTypeSchema.options;

export function WebhookManager(props: WebhookManagerProps) {
  const { orgId, endpoints, atLimit, onCreate, onDelete } = props;

  const [state, submit, pending] = useActionState<CreateState, FormData>(
    async (_previous, formData) => {
      const parsed = createWebhookSchema.safeParse({
        orgId,
        url: String(formData.get("url") ?? ""),
        eventTypes: formData.getAll("eventTypes").map(String),
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the endpoint details.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return onCreate(parsed.data);
    },
    null,
  );

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <div className="space-y-8">
      <ul className="space-y-2">
        {endpoints.map((endpoint) => (
          <li
            key={endpoint.id}
            className="flex items-start gap-4 rounded-md border border-slate-200 bg-white px-4 py-3 text-sm"
          >
            <div className="min-w-0 flex-1">
              <p className="truncate font-medium">{endpoint.url}</p>
              <p className="mt-0.5 text-xs text-slate-500">
                {endpoint.enabled ? "Enabled" : "Disabled"} · {endpoint.eventTypes}
              </p>
            </div>
            <button
              type="button"
              onClick={() => {
                void onDelete({ orgId, webhookId: endpoint.id as WebhookId });
              }}
              className="text-xs text-rose-600"
            >
              Delete
            </button>
          </li>
        ))}
      </ul>

      <form action={submit} className="space-y-4 border-t border-slate-200 pt-6">
        <h2 className="text-sm font-semibold">Add an endpoint</h2>

        {atLimit ? (
          <p className="rounded bg-amber-50 px-3 py-2 text-sm text-amber-800">
            This plan&apos;s webhook quota is full. Delete one first, or upgrade.
          </p>
        ) : null}

        {state?.ok === false && state.error.code === "plan_limit_exceeded" ? (
          <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
            {state.error.message}
          </p>
        ) : null}

        <div className="space-y-1">
          <label htmlFor="url" className="text-sm font-medium">
            Endpoint URL
          </label>
          <input
            id="url"
            name="url"
            type="url"
            required
            disabled={atLimit}
            placeholder="https://example.com/hooks/taskflow"
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
          />
          {fieldErrors.url !== undefined ? (
            <p className="text-xs text-rose-600">{fieldErrors.url[0]}</p>
          ) : null}
        </div>

        <fieldset className="space-y-2">
          <legend className="text-sm font-medium">Events</legend>
          <div className="grid gap-1 sm:grid-cols-2">
            {EVENT_TYPES.map((eventType) => (
              <label key={eventType} className="flex items-center gap-2 text-sm">
                <input
                  type="checkbox"
                  name="eventTypes"
                  value={eventType}
                  disabled={atLimit}
                />
                {eventType}
              </label>
            ))}
          </div>
          {fieldErrors.eventTypes !== undefined ? (
            <p className="text-xs text-rose-600">{fieldErrors.eventTypes[0]}</p>
          ) : null}
        </fieldset>

        <button
          type="submit"
          disabled={atLimit || pending}
          className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
        >
          {pending ? "Adding…" : "Add endpoint"}
        </button>
      </form>
    </div>
  );
}
----PAGE
/**
 * Webhook endpoints; gated on plan and the `webhooks` flag.
 *
 * Owner D. Three gates, in the order they matter: permission (may you manage
 * webhooks at all), flag (is the surface available), quota (how many more may
 * you add). Only the first is a 404 — the other two are explanations.
 *
 * Must call (do not reimplement): can, isEnabled, getPlanLimits
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { createWebhookAction } from "@/actions/webhooks/create-webhook";
import { deleteWebhookAction } from "@/actions/webhooks/delete-webhook";
import { EmptyState } from "@/components/ui/empty-state";
import { getPlanLimits } from "@/config/plan-limits";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listWebhooks } from "@/server/services/webhook-service";
import { loadTenantContext } from "../../_lib/tenant-context";
import { WebhookManager } from "./webhook-manager";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Webhooks",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "webhook:manage", {
    kind: "webhook",
    orgId: org.id,
    webhookId: null,
  });
  if (!allowed) {
    notFound();
  }

  if (!isEnabled("webhooks", buildFlagContext(actor, org))) {
    return (
      <EmptyState
        title="Webhooks are not part of this plan"
        description="Upgrade in Settings → Billing to push Taskflow events into your own systems."
      />
    );
  }

  const limits = getPlanLimits(org.plan);
  const endpoints = await listWebhooks(actor, org.id);

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-xl font-semibold tracking-tight">Webhooks</h1>
        <p className="mt-1 text-sm text-slate-600">
          {endpoints.length} of {limits.webhooks} endpoints used. Deliveries are
          signed and retried with backoff by the delivery job.
        </p>
      </header>

      <WebhookManager
        orgId={org.id}
        endpoints={endpoints}
        atLimit={endpoints.length >= limits.webhooks}
        onCreate={createWebhookAction}
        onDelete={deleteWebhookAction}
      />
    </div>
  );
}
----PLAN
import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}

